parameters.jsCode:
const b = $input.item.json.body || {};
// ILLUSTRATIVE limits - replace with your machine manufacturer's values
const limits = {
  temperature_c:    { warn: 75,   hard: 90 },
  vibration_mm_s:   { warn: 4.5,  hard: 7.1 },
  pressure_bar:     { warn: 8,    hard: 10 },
  runtime_hours:    { warn: 4000, hard: 5000 },
  last_service_days:{ warn: 90,   hard: 180 }
};
const flags = [];
let hard = false;
for (const [k, l] of Object.entries(limits)) {
  const v = Number(b[k]);
  if (b[k] === undefined || b[k] === null || b[k] === '' || Number.isNaN(v)) { flags.push(k + ': missing or invalid'); continue; }
  if (v >= l.hard) { flags.push(k + ' = ' + v + ' exceeds hard limit ' + l.hard); hard = true; }
  else if (v >= l.warn) { flags.push(k + ' = ' + v + ' above warning level ' + l.warn); }
}
return { json: {
  machine_id: b.machine_id || 'unknown',
  timestamp: b.timestamp || new Date().toISOString(),
  temperature_c: b.temperature_c, vibration_mm_s: b.vibration_mm_s, pressure_bar: b.pressure_bar,
  runtime_hours: b.runtime_hours, last_service_days: b.last_service_days,
  flags: flags, flag_text: flags.join('; '),
  hard_limit_breached: hard, is_anomalous: flags.length > 0
} };

