const out = $input.item.json.output || {};
const base = $('Rule Check').item.json;
const rank = ['Low', 'Medium', 'High', 'Critical'];
let sev = out.severity;
let guard = 'passed';
if (!rank.includes(sev)) { sev = 'High'; guard = 'failed: invalid AI severity, escalated for human review'; }
if (base.hard_limit_breached && rank.indexOf(sev) < rank.indexOf('High')) { sev = 'High'; guard = 'adjusted: hard limit breached, severity raised to High'; }
return { json: {
  ...base,
  severity: sev,
  probable_cause: out.probable_cause || 'n/a',
  key_factors: out.key_factors || 'n/a',
  recommended_action: out.recommended_action || 'Inspect machine manually',
  explanation: out.explanation || '',
  guard_check: guard,
  escalate: rank.indexOf(sev) >= 2
} };

